import json
from src.nodes.base import BaseNode
from src.runtime.reality import get_visual_review_engine

_EMPTY = {"review_json": "{}", "production_ready": False, "grade": "F",
          "score": 0.0, "artist_would_approve": False, "exec_out": True}

class Hou_Mcp_Visual_Review(BaseNode):
    name = "hou_mcp_visual_review"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("scene_layout_json", "string", widget_type="text", default="{}")
        self.add_output("review_json")
        self.add_output("production_ready", "bool")
        self.add_output("grade")
        self.add_output("score", "float")
        self.add_output("artist_would_approve", "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        try:
            scene = json.loads((inputs.get("scene_layout_json") or "{}").strip() or "{}")
        except Exception:
            self.log_error("scene_layout_json is not valid JSON.")
            return dict(_EMPTY)
        try:
            result = get_visual_review_engine().review(scene)
            for f in result.findings:
                self.log_error(f)
            return {
                "review_json": json.dumps(result.to_dict(), sort_keys=True, indent=2),
                "production_ready": result.production_ready,
                "grade": result.grade,
                "score": result.score,
                "artist_would_approve": result.artist_would_approve,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Visual review failed: {exc}")
            return dict(_EMPTY)

def register_node():
    return Hou_Mcp_Visual_Review
